import type { Locale } from "./i18n";
import { PREVIEWS } from "./previews.generated";

export type LocalizedText = Record<Locale, string>;

export type Plan = {
  slug: string;
  title: LocalizedText;
  summary: LocalizedText;
  style: string;
  areaM2: number;
  floors: number;
  bedrooms: number;
  garage: boolean;
  priceCents: number;
  /** Watermarked previews, first one is the cover. Generated by scripts/build-previews.mjs */
  gallery: string[];
  /** Object keys inside the private Supabase bucket, e.g. "villa-01/plan.pdf" */
  files: { pdf: string; dwg: string; cad: string };
  published: boolean;
};

